<?php namespace App\Models; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; class Opportunity extends Model{use HasFactory; protected $fillable=['company_id','external_id','title','type','potential_service','potential_value','status','probability','score','next_step_at','summary','source_url']; protected function casts():array{return ['potential_value'=>'decimal:2','next_step_at'=>'date','probability'=>'integer','score'=>'integer'];} public function company(){return $this->belongsTo(Company::class);} public function activities(){return $this->hasMany(Activity::class);} public function evidences(){return $this->hasMany(Evidence::class);}}
